//! WASM tool runtime for managing compiled components.//!//! Follows the principle: compile once at registration, instantiate fresh per execution.//! This matches NEAR blockchain patterns for deterministic, isolated execution.use std::collections::HashMap;use std::path::{Path, PathBuf};use std::sync::Arc;use std::time::Duration;use tokio::sync::RwLock;use wasmtime::{Config, Engine, OptLevel};use crate::tools::wasm::error::WasmError;use crate::tools::wasm::limits::{FuelConfig, ResourceLimits};/// Default epoch tick interval. Each tick increments the engine's epoch counter,/// which causes any store with an expired epoch deadline to trap.pub const EPOCH_TICK_INTERVAL: Duration = Duration::from_millis(500);/// Enable wasmtime's persistent compilation cache for a [`Config`].////// On Unix, this delegates to `cache_config_load_default()` which uses a/// shared cache directory. On Windows, each engine gets its own subdirectory/// (keyed by `label`) to avoid OS error 33 (`ERROR_LOCK_VIOLATION`) when/// multiple engines memory-map files in the same cache directory. See #448.////// If `explicit_dir` is `Some`, it is used as the cache directory on all/// platforms, bypassing the default.